\newcommand{\C}{\mathcal C}
\newcommand{\Set}{\mathbf{Set}}
\newcommand{\Nat}{\operatorname{Nat}}
\newcommand{\Hom}{\operatorname{Hom}}
\newcommand{\Sh}{\operatorname{Sh}}
\title{Yoneda Density, Reconstruction, and Isomorphism Detection\\for Presheaves and Sheaves}
\author{Aristotle}
\date{August 3, 2026}
\begin{document}
\maketitle

\begin{abstract}
Let $\C$ be a locally small category and $\widehat{\C}=[\C^{\mathrm{op}},\Set]$ its category of set-valued presheaves. We give a unified reconstruction theory around the Yoneda embedding $y:\C\to\widehat{\C}$. Every presheaf is canonically a colimit of representables indexed by maps from representables into it, yielding an extensionality principle for natural transformations. Pointwise bijective transformations of presheaves and sheaves are isomorphisms, while a morphism of $\C$ is invertible whenever it induces bijections on all represented hom-sets. We characterize the essential image of Yoneda, prove uniqueness of representing objects, establish the covariant dual statements, and show that represented sheaves retain object isomorphism classes on subcanonical sites. We conclude with finite algorithms that make the reconstruction and detection principles explicit.
\end{abstract}

\section{Introduction}
The Yoneda philosophy replaces internal inspection by a systematic record of interaction. An object $X$ is sent to $yX=\Hom_{\C}(-,X)$, recording every morphism from every test object into $X$. The Yoneda lemma recovers transformations from this record, and full faithfulness says that no morphism of $\C$ is lost.

The central result developed here is density: every presheaf is canonically assembled as a colimit of representables. Representables therefore form not merely an embedded copy of $\C$, but a system of generators adapted to all presheaves. This yields tests for equality and invertibility, a characterization of representability, and uniqueness of representing objects. The construction has a covariant dual and persists for sheaves, where local data satisfy gluing laws.

\section{Preliminaries}
\begin{definition}
A \emph{category} $\C$ consists of objects, sets $\Hom_{\C}(X,Y)$, identity morphisms, and associative composition. An \emph{isomorphism} $f:X\to Y$ admits $g:Y\to X$ with $gf=1_X$ and $fg=1_Y$.
\end{definition}

A functor preserves identities and composition. A \emph{presheaf} is a functor $F:\C^{\mathrm{op}}\to\Set$. Thus $u:S\to T$ induces a restriction $F(u):F(T)\to F(S)$. A natural transformation $\alpha:F\to G$ is a family $\alpha_X:F(X)\to G(X)$ commuting with all restriction maps.

\begin{definition}
For $X\in\C$, the \emph{represented presheaf} is
\[
yX=\Hom_{\C}(-,X).
\]
At $T$ it is $\Hom_{\C}(T,X)$, and $u:S\to T$ acts by precomposition. A morphism $f:X\to Y$ induces $yf:yX\to yY$ by postcomposition. These assignments define the \emph{Yoneda embedding} $y:\C\to\widehat{\C}$.
\end{definition}

\begin{definition}
A presheaf $F$ is \emph{representable} if there are $X\in\C$ and a natural isomorphism $yX\cong F$. Such an $X$ is a representing object.
\end{definition}

\begin{theorem}[Yoneda lemma]
For every $X\in\C$ and presheaf $F$, there is a natural bijection
\[
\Nat(yX,F)\cong F(X).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Send $\eta:yX\to F$ to $\eta_X(1_X)$. Given $x\in F(X)$, define $\eta^x_T(g)=F(g)(x)$ for $g:T\to X$. Functoriality proves naturality, and evaluation at the identity together with naturality shows that the constructions are inverse.
\end{proof}

\begin{corollary}[Full faithfulness]
For all $X,Y\in\C$, the map
\[
\Hom_{\C}(X,Y)\longrightarrow\Nat(yX,yY),\qquad f\longmapsto yf,
\]
is bijective.
\end{corollary}
\begin{proof}
Apply the Yoneda lemma to $F=yY$ and use $(yY)(X)=\Hom_{\C}(X,Y)$.
\end{proof}

\section{The category of elements and density}
\begin{definition}
For a presheaf $P$, its \emph{category of elements} $\int P$ has objects $(X,x)$ with $x\in P(X)$. A morphism $(X,x)\to(Y,y)$ is a morphism $u:X\to Y$ satisfying $P(u)(y)=x$.
\end{definition}

By Yoneda, $x\in P(X)$ corresponds to a map $\widehat{x}:yX\to P$. Hence $\int P$ is equivalently the category of arrows from representables into $P$. Define $D_P:\int P\to\widehat{\C}$ by $D_P(X,x)=yX$. The maps $\widehat{x}$ form the tautological cocone to $P$.

\begin{theorem}[Yoneda density]
The tautological cocone is colimiting. In particular,
\[
P\cong\mathop{\operatorname{colim}}_{(X,x)\in\int P}yX
\cong\mathop{\operatorname{colim}}_{(yX\to P)}yX.
\]
\end{theorem}
\begin{proof}[Proof sketch]
A cocone from $D_P$ to a presheaf $Q$ assigns compatible maps $\theta_{X,x}:yX\to Q$. By Yoneda each corresponds to $q_{X,x}\in Q(X)$. Set $\theta_X(x)=q_{X,x}$. Compatibility with a morphism $u:(X,x)\to(Y,y)$ gives
\[
Q(u)(\theta_Y(y))=\theta_X(P(u)(y)),
\]
which is naturality. Thus there is a unique $\theta:P\to Q$ inducing the cocone. Conversely, composition with the maps $\widehat{x}$ turns every $\theta$ into such a cocone. The constructions are inverse, proving the universal property.
\end{proof}

\begin{corollary}[Representable extensionality]
Let $\alpha,\beta:P\to Q$. If $\alpha\circ p=\beta\circ p$ for every object $X$ and every $p:yX\to P$, then $\alpha=\beta$.
\end{corollary}
\begin{proof}[Proof sketch]
The maps $p$ are the legs of the colimiting cocone. Maps out of a colimit are equal when they agree on every leg. Equivalently, choose the probe corresponding to each $x\in P(X)$ to obtain $\alpha_X(x)=\beta_X(x)$.
\end{proof}

\section{Isomorphism detection}
\begin{theorem}[Pointwise criterion for presheaves]
Let $\alpha:P\to Q$ be a natural transformation of set-valued presheaves. If every $\alpha_X:P(X)\to Q(X)$ is bijective, then $\alpha$ is a natural isomorphism.
\end{theorem}
\begin{proof}[Proof sketch]
Set $\beta_X=\alpha_X^{-1}$. From
\[
Q(u)\alpha_Y=\alpha_XP(u)
\]
and composition with the inverses, obtain $P(u)\beta_Y=\beta_XQ(u)$. Hence $\beta$ is natural, and the inverse equations hold componentwise.
\end{proof}

\begin{theorem}[Representable isomorphism detection]
Let $f:X\to Y$. If, for every $T\in\C$, postcomposition gives a bijection
\[
f_*:\Hom_{\C}(T,X)\longrightarrow\Hom_{\C}(T,Y),\qquad g\longmapsto f\circ g,
\]
then $f$ is an isomorphism.
\end{theorem}
\begin{proof}[Proof sketch]
These functions are the components of $yf$. The pointwise criterion makes $yf$ invertible. Full faithfulness identifies its inverse with $yg$ for a unique $g:Y\to X$, and reflects the natural inverse equations to $gf=1_X$ and $fg=1_Y$.
\end{proof}

\section{Reflection, essential image, and uniqueness}
\begin{theorem}[Reflection of object isomorphism]
For $X,Y\in\C$,
\[
X\cong Y\quad\Longleftrightarrow\quad yX\cong yY.
\]
\end{theorem}
\begin{proof}[Proof sketch]
An isomorphism induces an isomorphism under every functor. Conversely, full faithfulness turns a natural isomorphism and its inverse into morphisms $X\rightleftarrows Y$ and reflects their inverse equations.
\end{proof}

\begin{theorem}[Essential image]
A presheaf $F$ is representable if and only if there exists $X\in\C$ with $yX\cong F$. Thus the essential image of Yoneda consists exactly of representable presheaves.
\end{theorem}
\begin{proof}[Proof sketch]
The forward implication unpacks the definition of representation; the reverse implication uses the displayed isomorphism as a representation.
\end{proof}

\begin{theorem}[Uniqueness of representing objects]
If $F$ is represented by both $X$ and $Y$, then $X\cong Y$.
\end{theorem}
\begin{proof}[Proof sketch]
Compose $yX\cong F$ with the inverse of $yY\cong F$ to obtain $yX\cong yY$, then apply reflection of object isomorphism.
\end{proof}

These statements give the standard uniqueness principle for universal constructions. Different realizations may not be equal as constructed objects, but the functor they represent determines them up to isomorphism.

\section{Covariant duality}
For $X\in\C$, let $h^X=\Hom_{\C}(X,-):\C\to\Set$. This is ordinary Yoneda applied in $\C^{\mathrm{op}}$.

\begin{theorem}[Covariant full faithfulness]
For objects $X,Y\in\C^{\mathrm{op}}$, sending a morphism $f:X\to Y$ to the induced natural transformation of covariant represented functors is bijective.
\end{theorem}
\begin{proof}[Proof sketch]
Apply full faithfulness of Yoneda to $\C^{\mathrm{op}}$.
\end{proof}

\begin{theorem}[Covariant reflection]
Two objects of $\C^{\mathrm{op}}$ are isomorphic if and only if their covariant represented functors are naturally isomorphic.
\end{theorem}
\begin{proof}[Proof sketch]
Apply the preceding theorem and the same inverse-reflection argument as in the contravariant case.
\end{proof}

Thus an object can be recognized either by all arrows entering it or by all arrows leaving it.

\section{Sheaves and locality}
\begin{definition}
A \emph{sieve} on $X$ is a collection of arrows into $X$ closed under precomposition. A \emph{Grothendieck topology} $J$ designates covering sieves subject to maximality, pullback stability, and transitivity. A presheaf is a \emph{$J$-sheaf} if every compatible family of local sections on a covering sieve glues uniquely to a global section. The topology is \emph{subcanonical} if every representable presheaf is a sheaf.
\end{definition}

Write $\Sh(\C,J)$ for the category of set-valued sheaves. On a subcanonical site, Yoneda factors as $y_J:\C\to\Sh(\C,J)$.

\begin{theorem}[Pointwise criterion for sheaves]
Let $\alpha:F\to G$ be a morphism of set-valued $J$-sheaves. If $\alpha_X:F(X)\to G(X)$ is bijective for every $X$, then $\alpha$ is an isomorphism in $\Sh(\C,J)$.
\end{theorem}
\begin{proof}[Proof sketch]
Regard $\alpha$ as a presheaf transformation. The presheaf criterion supplies a natural inverse. Since morphisms of sheaves are precisely natural transformations of their underlying presheaves, this inverse is also a sheaf morphism.
\end{proof}

\begin{theorem}[Reflection on a subcanonical site]
If $(\C,J)$ is subcanonical, then for all $X,Y\in\C$,
\[
X\cong Y\quad\Longleftrightarrow\quad y_JX\cong y_JY
\]
as sheaves.
\end{theorem}
\begin{proof}[Proof sketch]
The forward implication is functoriality. For the converse, the sheaf-valued Yoneda embedding is fully faithful because representables are sheaves and morphisms between them are the same underlying natural transformations. It therefore reflects the inverse equations of an isomorphism.
\end{proof}

\section{Finite algorithms and examples}
For a finite category and $f:X\to Y$, enumerate every test object $T$ and compute $f_*:\Hom(T,X)\to\Hom(T,Y)$. Hashing detects injectivity and surjectivity. If $N$ is the number of objects and $M$ bounds the hom-set sizes, the procedure uses $O(NM)$ compositions and $O(M)$ auxiliary space per test object, assuming constant expected-time hashing.

A finite presheaf can be reconstructed by enumerating $\int P$. At $T$, form
\[
\coprod_{(X,x)\in\int P}\Hom(T,X)
\]
and map $(X,x,g)$ to $P(g)(x)$. Quotient by relations generated by morphisms in $\int P$. A union--find implementation performs the quotient phase in $O((E+R)\alpha(E))$ time for $E$ representatives and $R$ relations.

For finite sets $|T|=k$ and $|X|=m$,
\[
|\Hom(T,X)|=m^k.
\]
Postcomposition by $f:X\to Y$ applies $f$ coordinatewise to $k$-tuples. It is bijective for every $k$ exactly when $f$ is bijective. The singleton test already identifies the induced map with $f$ itself.

\section{Applications}
In algebra, free objects, tensor products, and dual constructions are frequently defined by represented functors; uniqueness of representing objects gives their canonical uniqueness. Additive versions suggest density in categories of additive functors.

In geometry, $T\mapsto\Hom(T,X)$ is the functor of points. Reflection says that retaining all test objects and naturality determines $X$ up to isomorphism. A moduli problem is represented precisely when its functor is naturally isomorphic to one such functor of points.

In topology and geometry, sheaves organize compatible local observations. The pointwise sheaf criterion turns objectwise bijections into global equivalences, while subcanonical reflection ensures that represented sheaves do not identify nonisomorphic source objects.

In categorical semantics, presheaves and sheaves describe data varying over contexts. Representables are basic contexts, density reconstructs arbitrary varying data from them, and extensionality compares transformations context by context.

\section{Discussion and future work}
The results form a reconstruction pipeline. Full faithfulness recovers morphisms between representables. Density promotes representables to generators of all presheaves. Extensionality turns generation into an equality test. Pointwise bijectivity detects natural isomorphisms, and full faithfulness transports invertibility and object identity back to $\C$. Representability identifies the essential image, uniqueness follows by reflection, dualization handles outgoing probes, and subcanonical sheaf theory preserves recognition under local-to-global constraints.

Five extensions stand out. Additive density should reconstruct every additive presheaf on a preadditive category as a colimit of additive representables in the additive functor category. A representability theorem should derive representation from preservation of small limits together with a solution-set condition. Sheaf density should reconstruct each sheaf on a subcanonical site as a sheaf-category colimit of represented sheaves. Classifier uniqueness should show that two subobject classifiers are uniquely isomorphic compatibly with their truth arrows. Finally, predicate extensionality should identify equality of subobjects with equality of characteristic maps to the classifier, naturally under pullback.

\section{Conclusion}
Yoneda theory turns interaction into reconstruction. Every object is faithfully encoded by its incoming maps; every presheaf is canonically assembled from such encodings; and maps out of a presheaf are determined on representable probes. Componentwise bijections detect presheaf and sheaf isomorphisms. Represented hom-sets detect invertibility in the original category. Natural isomorphism of representables detects object isomorphism, the essential image is exactly the representable presheaves, and representing objects are unique up to isomorphism. Covariant duality and the sheaf extension show that this principle survives reversal of viewpoint and imposition of locality.

\end{document}

